<template>
    <section class="kw-database">
        <div class="kw-row"><label>资料库<select id="kw-database" :value="selected" class="input" @change="changeSelection($event.target)"><option value="">新建资料库…</option><option v-for="item in databases" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><button class="btn" @click="newDatabase">新建</button><button v-if="database" class="btn btn-danger" :disabled="busy" @click="remove">删除资料库</button><button v-if="database" class="btn btn-primary" @click="$emit('create', database.data.templateId || '', database.id)">新增资料笔记</button></div>
        <p v-if="error" class="workshop-error" role="alert">{{ error }}</p><p v-if="notice" class="workshop-success" role="status">{{ notice }}</p>
        <details class="kw-details" :open="!database"><summary>资料库字段与页面模板</summary>
            <label>名称<input v-model="draft.name" class="input" maxlength="80" /></label><label>新页面使用的模板<select v-model="draft.data.templateId" class="input"><option value="">空白页面</option><option v-for="template in templates" :key="template.id" :value="template.id">{{ template.name }}</option></select></label>
            <div v-for="(field, index) in draft.data.fields" :key="index" class="kw-field-editor"><input v-model="field.label" class="input" placeholder="属性名称" aria-label="属性名称" maxlength="40" /><input v-model="field.key" class="input" placeholder="英文标识" aria-label="属性标识" maxlength="24" /><select v-model="field.type" class="input" aria-label="属性类型" @change="fieldChanged(field)"><option v-for="(label, type) in fieldLabels" :key="type" :value="type">{{ label }}</option></select><input v-if="['status','multi'].includes(field.type)" class="input" :value="field.options?.join('，')" placeholder="选项，用逗号分隔" aria-label="属性选项" @input="field.options = $event.target.value.split(/[,，]/).map(s=>s.trim()).filter(Boolean)" /><select v-if="field.type === 'relation'" v-model="field.target" class="input" aria-label="关联资料库"><option v-for="item in databases" :key="item.id" :value="item.id">{{ item.name }}</option></select><template v-if="field.type === 'rollup'"><select v-model="field.relation" class="input" aria-label="汇总关联属性"><option v-for="item in draft.data.fields.filter(f => f.type === 'relation')" :key="item.key" :value="item.key">{{ item.label }}</option></select><select v-model="field.aggregate" class="input" aria-label="汇总方法"><option value="count">关联数量</option><option value="sum">数字求和</option><option value="average">数字平均</option></select><select v-if="field.aggregate !== 'count'" v-model="field.field" class="input" aria-label="汇总目标字段"><option value="">选择数字属性</option><option v-for="targetField in rollupFields(field)" :key="targetField.key" :value="targetField.key">{{ targetField.label }}</option></select></template><button class="btn btn-sm" @click="draft.data.fields.splice(index, 1)">移除</button></div>
            <button class="btn btn-sm" :disabled="draft.data.fields.length >= 24" @click="addField">添加属性</button><button class="btn btn-primary" :disabled="busy" @click="saveConfig">保存资料库配置</button><p class="kw-muted">已有值的属性不能直接删除或改类型，需先清空对应笔记属性。人员属性为标签；多选与关联可按 Ctrl/Cmd 多选。</p>
        </details>
        <template v-if="database"><div class="kw-row kw-view-tabs"><button v-for="(label, type) in viewLabels" :key="type" class="btn btn-sm" :class="{'is-active': view.type === type}" @click="view.type = type">{{ label }}</button><label>已保存视图<select class="input" :value="savedIndex" @change="chooseView(Number($event.target.value))"><option value="-1">当前临时视图</option><option v-for="(item,index) in database.data.views" :key="index" :value="index">{{ item.name }}</option></select></label></div>
            <details class="kw-details"><summary>筛选、排序、分组与保存视图</summary><div class="kw-controls"><label>分组字段<select v-model="view.group" class="input"><option value="">不分组</option><option v-for="field in fields.filter(f => !['relation','rollup','range'].includes(f.type))" :key="field.key" :value="field.key">{{ field.label }}</option></select></label><label>排序字段<select v-model="view.sort" class="input"><option value="">默认顺序</option><option value="title">标题</option><option v-for="field in fields" :key="field.key" :value="field.key">{{ field.label }}</option></select></label><label>方向<select v-model="view.direction" class="input"><option value="asc">升序</option><option value="desc">降序</option></select></label><label>日历/时间线日期<select v-model="view.dateField" class="input"><option value="">请选择日期属性</option><option v-for="field in fields.filter(f => ['date','range'].includes(f.type))" :key="field.key" :value="field.key">{{ field.label }}</option></select></label></div>
                <div v-for="(filter,index) in view.filters" :key="index" class="kw-row"><select v-model="filter.field" class="input" aria-label="筛选字段"><option value="title">标题</option><option v-for="field in fields" :key="field.key" :value="field.key">{{ field.label }}</option></select><select v-model="filter.op" class="input" aria-label="筛选方法"><option value="contains">包含</option><option value="equals">等于</option><option value="empty">未设置</option><option value="not-empty">已设置</option></select><input v-model="filter.value" class="input" aria-label="筛选值" maxlength="200" /><button class="btn btn-sm" @click="view.filters.splice(index,1)">移除筛选</button></div><div class="kw-row"><button class="btn btn-sm" :disabled="view.filters.length >= 8" @click="view.filters.push({field:'title',op:'contains',value:''})">添加筛选</button><input v-model="view.name" class="input" maxlength="40" aria-label="视图名称" placeholder="视图名称" /><button class="btn btn-sm" :disabled="busy" @click="saveView">保存视图</button><button class="btn btn-sm" :disabled="busy || savedIndex < 0" @click="deleteView">删除此视图</button></div>
            </details>
            <p class="kw-muted">{{ rows.length }}篇资料 · 点击标题打开；属性在笔记内编辑，各视图共用同一份数据。</p>
            <div v-if="view.type === 'table'" class="kw-table-wrap"><template v-for="group in groups" :key="group.name"><h3 v-if="view.group">{{ group.name }}（{{ group.items.length }}）</h3><table class="kw-table"><thead><tr><th>笔记</th><th v-for="field in fields" :key="field.key">{{ field.label }}</th></tr></thead><tbody><tr v-for="note in group.items" :key="note.id"><td><button class="kw-link" @click="$emit('open',note.id)">{{ note.title }}</button></td><td v-for="field in fields" :key="field.key">{{ format(note,field) }}</td></tr></tbody></table></template></div>
            <div v-else-if="view.type === 'board'" class="kw-board"><section v-for="group in boardGroups" :key="group.name" class="kw-board-column" @dragover.prevent @drop.prevent="moveCard(group.name)"><h3>{{ group.name }} · {{ group.items.length }}</h3><button v-for="note in group.items" :key="note.id" class="kw-card" :draggable="!!statusField" @dragstart="dragId = note.id; $event.dataTransfer.setData('text/plain',String(note.id))" @dragend="dragId = null" @click="$emit('open',note.id)"><strong>{{ note.title }}</strong><span>{{ note.snippet }}</span></button></section></div>
            <div v-else-if="view.type === 'gallery'" class="kw-gallery"><section v-for="group in groups" :key="group.name"><h3 v-if="view.group">{{ group.name }}</h3><div class="kw-gallery-grid"><button v-for="note in group.items" :key="note.id" class="kw-card" @click="$emit('open',note.id)"><strong>{{ note.title }}</strong><span>{{ note.snippet || '空白笔记' }}</span><span v-for="field in fields.slice(0,4)" :key="field.key">{{ field.label }}：{{ format(note,field) }}</span></button></div></section></div>
            <template v-else-if="view.type === 'calendar'"><div class="kw-row"><button class="btn btn-sm" @click="changeMonth(-1)">上个月</button><input v-model="month" class="input" type="month" aria-label="日历月份" /><button class="btn btn-sm" @click="changeMonth(1)">下个月</button></div><p v-if="!view.dateField" class="workshop-note">请在视图设置中选择日期或日期范围属性。</p><div v-else class="kw-calendar"><div v-for="day in ['一','二','三','四','五','六','日']" :key="day" class="kw-calendar-label">周{{ day }}</div><section v-for="day in calendarDays" :key="day" class="kw-calendar-day" :class="{'is-muted': !day.startsWith(month)}"><time>{{ day.slice(5) }}</time><button v-for="note in rows.filter(n=>inDay(n,day))" :key="note.id" class="kw-link" @click="$emit('open',note.id)">{{ note.title }}</button></section></div><p class="kw-muted">{{ rows.filter(n=>!dates(n).start).length }}篇尚未设置日期。</p></template>
            <template v-else-if="view.type === 'timeline'"><p v-if="!view.dateField" class="workshop-note">请先选择日期或日期范围属性。</p><p class="kw-muted">{{ timeline.start }} ～ {{ timeline.end }}</p><div class="kw-timeline"><div v-for="note in rows" :key="note.id" class="kw-timeline-row"><button class="kw-link" @click="$emit('open',note.id)">{{ note.title }}</button><div class="kw-timeline-track"><button v-if="dates(note).start" class="kw-timeline-bar" :style="barStyle(note)" @click="$emit('open',note.id)">{{ dates(note).start }} ～ {{ dates(note).end }}</button><span v-else class="kw-muted">未设置日期</span></div></div></div></template>
            <p v-if="!rows.length" class="kw-empty">暂无符合筛选条件的笔记。新增资料笔记或在笔记属性里选择此资料库。</p>
        </template>
    </section>
</template>
<script setup>
import { ref, computed, watch, onBeforeUnmount } from 'vue';
import { kbApi } from '../../api/knowledge-workbench-client.js';
import { fieldLabels, viewLabels, visibleDatabaseNotes, groupNotes, propertyValue, displayValue, localDay } from '../../utils/knowledge-workbench.js';
const clone=value=>JSON.parse(JSON.stringify(value));
const props = defineProps({ entries: Array, notes: Array }), emit = defineEmits(['changed','open','create']);
const databases = computed(()=>props.entries.filter(e=>e.kind==='database')), templates = computed(()=>props.entries.filter(e=>e.kind==='template')), selected=ref(''), draft=ref({name:'',kind:'database',data:{fields:[],views:[]}}), busy=ref(false), error=ref(''), notice=ref(''), dragId=ref(null), month=ref(localDay().slice(0,7)), savedIndex=ref(-1);
const emptyView=()=>({name:'默认视图',type:'table',group:'status',sort:'title',direction:'asc',dateField:'date',filters:[]}),view=ref(emptyView());
const database=computed(()=>databases.value.find(d=>d.id===selected.value)), fields=computed(()=>database.value?.data.fields || []), rows=computed(()=>visibleDatabaseNotes(database.value,view.value,props.notes,databases.value)),groups=computed(()=>database.value?groupNotes(rows.value,view.value.group,database.value,props.notes,databases.value):[]),statusField=computed(()=>fields.value.find(f=>f.key===view.value.group&&f.type==='status'));
const boardGroups=computed(()=>statusField.value?[...statusField.value.options,'—'].map(name=>({name,items:rows.value.filter(n=>displayValue(n.meta.values[statusField.value.key])===name)})):groups.value);
let controller=new AbortController(),alive=true,baseline='',viewBaseline='';
const dirty=computed(()=>baseline!==JSON.stringify(draft.value)||viewBaseline!==JSON.stringify(view.value));
function markSaved(){baseline=JSON.stringify(draft.value);viewBaseline=JSON.stringify(view.value);}
function changeSelection(selectElement){if(!canLeave()){selectElement.value=selected.value;return;}selected.value=selectElement.value;loadDraft();}
function newDatabase(){if(!canLeave())return;selected.value='';loadDraft();}
function rollupFields(field){const relation=draft.value.data.fields.find(f=>f.key===field.relation);return databases.value.find(d=>d.id===relation?.target)?.data.fields.filter(f=>f.type==='number')||[];}
function loadDraft(){ draft.value=database.value?clone(JSON.parse(JSON.stringify(database.value))):{kind:'database',name:'新资料库',data:{fields:[{key:'status',label:'状态',type:'status',options:['待办','进行中','完成']},{key:'date',label:'日期',type:'date'},{key:'amount',label:'数量',type:'number'}],views:[emptyView()],templateId:''}}; view.value=clone(database.value?.data.views[0] || emptyView()); savedIndex.value=database.value?.data.views.length?0:-1; markSaved(); }
watch(()=>databases.value.map(d=>d.id+':'+d.version).join(','),()=>{if(baseline&&dirty.value)return;if(!selected.value&&databases.value.length)selected.value=databases.value[0].id; if(selected.value&&!database.value)selected.value=''; loadDraft();},{immediate:true});
function fieldChanged(field){ if(['status','multi'].includes(field.type))field.options=['待办','进行中','完成'];if(field.type==='relation')field.target=databases.value[0]?.id||'';if(field.type==='rollup'){field.relation=draft.value.data.fields.find(f=>f.type==='relation')?.key||'';field.field='';field.aggregate='count';}}
function addField(){let i=1;while(draft.value.data.fields.some(f=>f.key==='field'+i))i++;draft.value.data.fields.push({key:'field'+i,label:'新属性',type:'text'});}
async function run(task){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const result=await task(controller.signal);if(alive){emit('changed');notice.value='已保存';return result;}}catch(failure){if(alive&&!controller.signal.aborted)error.value=failure.message;}finally{if(alive)busy.value=false;}}
async function saveConfig(){const result=await run(signal=>kbApi.saveEntry(draft.value,signal));if(result){selected.value=result.id;draft.value=clone(result);markSaved();}}
function chooseView(index){if(viewBaseline!==JSON.stringify(view.value)&&!confirm('当前视图有未保存修改，切换会丢弃。继续？'))return;savedIndex.value=index;if(index>=0)view.value=clone(database.value.data.views[index]);viewBaseline=JSON.stringify(view.value);}
async function saveView(){const data=clone(database.value.data);if(savedIndex.value>=0)data.views[savedIndex.value]=clone(view.value);else data.views.push(clone(view.value));const result=await run(signal=>kbApi.saveEntry({...database.value,data},signal));if(result){draft.value=clone(result);markSaved();}}
async function deleteView(){if(!confirm('永久删除此保存视图？笔记资料保留。'))return;const data=clone(database.value.data);data.views.splice(savedIndex.value,1);const result=await run(signal=>kbApi.saveEntry({...database.value,data},signal));if(result){draft.value=clone(result);markSaved();}}
async function remove(){if(!confirm('永久删除资料库配置？有笔记或其他项目引用时会拒绝删除。'))return;await run(signal=>kbApi.remove(database.value,signal));}
function format(note,field){return displayValue(propertyValue(note,field,database.value,props.notes,databases.value),field,props.notes);}
async function moveCard(name){const id=dragId.value;dragId.value=null;if(!id||!statusField.value)return;const key=statusField.value.key;await run(async signal=>{const note=await kbApi.note(id,signal);return kbApi.saveNote(id,{version:note.version,meta:{...note.meta,values:{...note.meta.values,[key]:name==='—'?'':name}}},signal);});}
function dates(note){const raw=note.meta.values[view.value.dateField];return typeof raw==='string'?{start:raw,end:raw}:raw||{start:'',end:''};}
function inDay(note,day){const range=dates(note);return range.start&&range.start<=day&&range.end>=day;}
const calendarDays=computed(()=>{const parsed=/^\d{4}-\d{2}$/.test(month.value)?month.value:localDay().slice(0,7);const day=new Date(parsed+'-01T12:00:00');day.setDate(day.getDate()-((day.getDay()+6)%7));return Array.from({length:42},(_,index)=>{const copy=new Date(day);copy.setDate(copy.getDate()+index);return localDay(copy);});});
function changeMonth(delta){const day=new Date((month.value||localDay().slice(0,7))+'-01T12:00:00');day.setMonth(day.getMonth()+delta);month.value=localDay(day).slice(0,7);}
const timeline=computed(()=>{const ranges=rows.value.map(dates).filter(d=>d.start),starts=ranges.map(d=>d.start).sort(),ends=ranges.map(d=>d.end).sort();return{start:starts[0]||localDay(),end:ends.at(-1)||localDay()};});
function barStyle(note){const range=dates(note),start=Date.parse(timeline.value.start),span=Math.max(86400000,Date.parse(timeline.value.end)-start+86400000);return{marginInlineStart:`${Math.max(0,(Date.parse(range.start)-start)/span*100)}%`,width:`${Math.max(1,(Date.parse(range.end)-Date.parse(range.start)+86400000)/span*100)}%`};}
function canLeave(){return !busy.value&&(!dirty.value||confirm('资料库配置或视图尚未保存，离开会丢弃。继续？'));}
onBeforeUnmount(()=>{alive=false;controller.abort();});defineExpose({canLeave,dirty});
</script>
